cd /workspace && /opt/mtg-data/venv/bin/python - <<'EOF'
import gzip, json, collections
fra=json.load(open('/workspace/work/fra_main_cards.json'))
fra_names={c['name'] for c in fra}
fra_oracle={c['oracle_id'] for c in [json.loads(l) for l in gzip.open('/opt/mtg-data/scryfall/sets/fra.jsonl.gz','rt') if l.strip()]}
# check historical sets for same names / oracle ids
for s in ['tdm','fin','eoe','om1','tla','ecl','tmt','sos','msh','hob']:
    cards=[json.loads(l) for l in gzip.open(f'/opt/mtg-data/scryfall/sets/{s}.jsonl.gz','rt') if l.strip()]
    b=[c for c in cards if c.get('booster')]
    names={c['name'] for c in b}
    same=names & fra_names
    print(s, len(cards), 'booster', len(b), 'unique', len(names), 'overlap with FRA:', same)
# Check default-cards for FRA names in other sets (reprints), e.g., Unsummon, Last Gasp, Tarmogoyf
print('--- reprints in default-cards (any set) ---')
cnt=collections.defaultdict(set)
with gzip.open('/opt/mtg-data/scryfall/default-cards.jsonl.gz','rt') as f:
    for l in f:
        c=json.loads(l)
        if c.get('name') in fra_names and c.get('set')!='fra' and c.get('lang')=='en':
            cnt[c['name']].add((c['set'], c.get('released_at','')[:4]))
for n,v in sorted(cnt.items()):
    print(n, sorted(v)[:8])
EOF

